WITH long_format AS (SELECT id, status, metric_name, val FROM (SELECT id, status, shipping_fee, discount, amount FROM orders) src UNPIVOT INCLUDE NULLS (val FOR metric_name IN (shipping_fee, discount AS DISCOUNT, amount AS AMOUNT_VAL))) SELECT status, PERCENTILE_APPROX(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles, COUNT(CASE WHEN status = 'SHIPPED' THEN 1 END) AS shipped_count, MAX(val) AS max_val, COUNT(*) FILTER (WHERE metric_name = 'shipping_fee') AS shipping_fee_rows, COUNT(CASE WHEN metric_name = 'AMOUNT_VAL' THEN 1 END) AS amount_val_count FROM long_format GROUP BY 1 ORDER BY amount_val_count
